# -*- coding: utf-8 -*-
import sys; sys.path.insert(0, "Tools/prd_ledger/85")
from _lib import c, table, save

c(1, "header lines 1-5; §2.1; §2.1 table (verbatim); §2.2 table (verbatim); §2.2 bullets", "positioning", "Habitica: Gamified Taskmanager (App Store ID 994882113) by HabitRPG, Inc. (com.habitrpg.ios.Habitica), Productivity, open source, released 2015-07-07, current 4.0.7 (2026-08-20), iOS 17.6+, 12+, 18 declared languages (not Korean or Turkish) — a task manager dressed as a 16-bit RPG: Habits (+/− counters), Dailies (scheduled, reset daily, cost health if missed), To-Dos; XP and gold buy gear or custom real-life rewards; levels, classes, pets, mounts; parties fight quest bosses and missed Dailies damage the whole party; gems (paid second currency) and cosmetics; guilds and tavern chat closed August 2023 (the US description still lists Guilds); challenges remain; also on web and Android. Capability table (verbatim): " + table("## 2.1 What the product is", 0) + " || storefront table (verbatim): " + table("## 2.2 What the store listing says", 0) + " — 'Habitica can be fully enjoyed for free, but if you would like to help support us, we offer optional in-app purchases and subscriptions'; $4.99/month, $14.99/3mo, $29.99/6mo, $47.99/yr; in all 11 eligible storefronts the public mean exceeds the corpus mean by 0.26–0.78★.", "free core, optional subscription + gem currency", "mixed", "3,445 reviews, 83 storefronts, 21 languages (English 2,697), 2015-07-07 → 2026-09-06, mean 3.71★; 1–2★ 788 (22.87%); 183 hand codes; 816 checks", "none", "header", "app-specific", ["1223698024", "14516534730"], "", "eleven-year corpus spanning several products")

c(2, "How to read this; Eight warnings 1, 4, 6, 8; §1.1 table (verbatim); §1.2 table (verbatim); §1.3; §1.4; §1.5 table (verbatim); §1.6", "data-caveat", "Method and limits: every one of 3,445 reviews read in 35 batches in the original language and hand-coded with a quoted note per line, IDs filled from the index so an ID cannot drift from its text; 183 hand codes, 7 unions; 816 checks, 0 failures; build refuses to write if a quotation is not verbatim; no duplicates, 3 authors on >1 storefront, 61 edited, 406 with votes (max 89); mostly US/English (us 42.99%, English 78.29%; 11 storefronts ≥50); eleven years and several products, no version field, eras dated from what reviewers say; reviewers often describe the website or Android, codes follow what they say; E4 has 215 reviews; outcomes self-reported. Bands (verbatim): " + table("## 1.5 Signal thresholds", 0) + " — 0.1% ≈ 3 reviews, 1% ≈ 34, 5% ≈ 172.", "n/a", "mixed", "3,445/3,445 read; 183 codes; 816 checks", "none", "method", "generalisable", ["1223698024"], "", "")

c(3, "Warning 2, 7; §2.2 (public vs corpus); §4.3", "data-caveat", "Written reviews are harsher than the star ratings: corpus 3.71★, 1–2★ 22.87%; the US listing shows 4.27★ from 3,324 ratings vs a US corpus mean of 3.76★ — 'people write when something breaks'; in all 11 eligible storefronts the public mean exceeds the corpus mean by 0.26–0.78★ (public counts may reflect rating resets); CONTRA_RATING 46 (1.34%) — 44 are 5★ reviews reporting a defect, kept and coded by text.", "n/a", "mixed", "US public 4.27 vs corpus 3.76; gap 0.26–0.78 across 11; CONTRA 46", "none", "High-priority", "generalisable", ["1223698024"], "", "")

c(4, "Warning 3; §0.2 wave table (verbatim); §7.6", "data-caveat", "Defect reviews come in waves: a single day, 2021-08-20, holds 49 reviews, 47 of them crash reports; era and year shares are sensitive to these bursts and §7.6 recomputes headlines without them. The waves (verbatim): " + table("## 0.2 Reliability is the largest", 0), "n/a", "1★-burst", "2021-08-20: 49 reviews / 47 crashes; 2016-11 72 / 54; 2017-10 86 / 45; 2018-02 67 (13 sign-up, 13 server); 2023-09-16 20 / 17 server", "none", "High-priority", "generalisable", ["7712740288", "1483848155"], "", "")

c(5, "§0.1; §3.2", "insight", "The RPG layer is what people come for, and it works for them: PR_GAMIFY 468 (13.58%, mean 4.72★ vs corpus 3.71); PR_PARTY 158 (4.59%), PR_COLLECT 88 (2.55%), PR_PENALTY 34 (0.99%: losing health for missed Dailies is the pressure they need); outcome evidence is broad — U_OUTCOME 502 (14.57%, 4.70★): OUT_PRODUCTIVE 197 (5.72%), OUT_LIFE 179 (5.20%), OUT_HABIT 164 (4.76%), OUT_RESULT 27; PR_STICKY 78 (2.26%) the first or only such app they kept using; 'i stopped biting my nails, eating in the car'; 'Para pessoas com depressão, como eu, esse aplicativo é incrível' (18 votes, the most-voted purely positive review); 'Points go in where you can see them, so you want to do it even when you're not motivated' (jp); 'I still have adhd but now I feel anxious that my team could get dmg because of me not doing the dishes'.", "free RPG layer: XP, gold, levels, pets, parties, health penalty", "praise", "PR_GAMIFY 468 / 13.58% / 4.72★; U_OUTCOME 502 / 14.57% / 4.70★; PR_PARTY 158; PR_COLLECT 88; PR_PENALTY 34; PR_STICKY 78", "build-free", "High-priority", "generalisable", ["1812242046", "1930536403", "14515415839", "14180891534", "1223786048", "1350667396"], "", "social accountability (party damage) is the mechanism named by ADHD users")

c(6, "§0.2; §3.3; §8.1", "must-never-break", "Reliability is the largest complaint and arrives in waves after updates: U_BUG_ANY 1428 (41.45%, mean 2.81★) — BUG_CRASH 415 (12.05%), BUG_REGRESSION 201 (5.83%, blame a specific update), BUG_TASK 218 (6.33%: tasks will not check off, save or appear), BUG_SLOW 162 (4.70%), BUG_SIGNUP 139 (4.03%, mean 1.55★), BUG_SERVER 126 (3.66%), BUG_SYNC 106 (3.08%: lost or reverted data), BUG_RESET 93 (2.70%: Dailies fail to roll over); 'Crashes after a few seconds on the Rewards page'; 'The latest 2 versions of the app have ceased to work at all for me. They crash on startup'; 'the app will tell me it started a new day, but it hasn't cleared out my dailies'; crash reports fall to 2.1% of reviews from 2024 (16.2% in 2015–16) — the newer defects are quieter and more corrosive (Dailies not resetting, taps landing on the wrong task, widgets not refreshing); reviewers trade workarounds (REV_TIP 33, most often reinstalling).", "recurring post-update crash waves; day-rollover failures", "1★-burst", "U_BUG_ANY 1428 / 41.45% / 2.81★; CRASH 415; REGRESSION 201; TASK 218; SLOW 162; SIGNUP 139 / 1.55★; SERVER 126; SYNC 106; RESET 93; crash 16.2% → 2.1%", "must-never-break", "High-priority", "generalisable", ["1483848155", "1835618625", "7712740288", "13838933613", "1283121208", "1491945962", "14516534730"], "", "")

c(7, "§0.3; §3.4; §8.8", "contradiction", "The iPhone app has trailed the website and Android for a decade: NEG_PARITY 141 (4.09%, 3.77★) — challenges, guild management, the market, stats and inbox exist only on the web and the web is faster; 199 (5.78%) mention the website at all; NEG_IOS_BEHIND 21 — Korean and Ukrainian on Android not iPhone, a Wear OS watch app but no watchOS ('安卓使用者是人，蘋果不是人喔' — Android users are people, Apple users aren't?; 'It doesn't make sense that Habitica hasn't released for Apple Watch but Wear Os'); REQ_WIDGET 68 (1.97%), REQ_WATCH 67 (1.94%), NEG_OFFLINE 55 (1.60%); widgets arrived and became a defect source (BUG_WIDGET 22, all from 2021); the corpus's last review (2026-09-06, 5★) recommends the website as the workaround for the app.", "iOS client behind web/Android; no Watch; widgets buggy", "complaint", "NEG_PARITY 141 / 4.09%; IOS_BEHIND 21; REQ_WIDGET 68; REQ_WATCH 67; NEG_OFFLINE 55; BUG_WIDGET 22", "must-have", "Very strong", "generalisable", ["1833698218", "4362725195", "12612023060", "14516534730", "1223779586", "1349985635"], "", "")

c(8, "§0.4; §3.5; §8.7", "timeline", "Removing the community in 2023 cost the most committed users: a staff–volunteer-moderator dispute (STAFF_CONTROVERSY 19, 0.55%, mean 1.74★, 2022-12 → 2024-11: 'When workers asked for better conditions, they were treated disrespectfully and many were fired') and the closure of guilds and the tavern on 8 August 2023 (NEG_GUILD_SHUTDOWN 32, 0.93%, mean 2.25★, 2023-08 → 2026-02: 'The guilds were the soul of this app'; 'I have ADHD, and I was in a guild that basically acted as a sort of support group'); together 43 reviews at 2.12★, 23.3% of them multi-year users vs 3.86% of all; E4 (2022-12 → 2023-12) is the lowest-rated era (3.37★); two of these rank 11th and 13th by votes of all 3,445; PR_COMMUNITY falls 4.4% of E3 → 1.0% of E5; parties survived and party praise holds at 5.0% of E5; the guild complaint continues to 2026-02-26 from a user returning after two years.", "shut down public guilds and tavern chat 2023-08-08", "churn", "STAFF_CONTROVERSY 19 / 1.74★; GUILD_SHUTDOWN 32 / 2.25★; 43 combined / 2.12★; E4 3.37★; PR_COMMUNITY 4.4% → 1.0%", "product-rule", "Emerging", "generalisable", ["9423739332", "10215290731", "12975896573", "13791199455", "9506002892", "10211945336"], "the community was a mental-health support surface for the most engaged cohort", "")

c(9, "§0.5; §3.7; §8.3", "market", "Missing languages are the most-voted complaint: NEG_LANG 195 (5.66%, 3.46★, 2015 → 2026); of the six most-voted reviews five are from the Turkish storefront and four of the six ask for Turkish (154 votes between them); the single most-voted review (89 votes) is a Turkish user telling those reviewers to learn English; in Korea 40 of 52 reviews (76.9%) are about the missing Korean translation ('Why does Android have Korean and iPhone doesn't?'); the translations are volunteer work and a volunteer reports the finished Ukrainian iOS translation had not shipped (2026-05-18) while 'Немає української мови' (1★); the listing now declares 18 languages incl. Ukrainian and Hebrew but not Korean or Turkish ('Man, there's even Hebrew but no Turkish'); partial translation is its own defect — mixed-language screens make up much of BUG_DISPLAY in cn (20 of 63).", "18 languages; Korean/Turkish absent; volunteer translations unshipped", "complaint", "NEG_LANG 195 / 5.66% / 3.46★; tr top-voted 4 of 6 (154 votes); kr 40 of 52 (76.9%)", "do", "High-priority", "generalisable", ["10028573967", "11637734854", "14078142287", "14126986905", "1237532014", "1627387423"], "", "a completed volunteer translation left unshipped becomes a 1★ generator")

c(10, "§0.6; §3.2 (free); §5.5; §8.5", "monetization", "The free core earns goodwill; the gem economy spends it: PR_FREE 68 (1.97%), MON_NOT_REQUIRED 44 (1.28%: 'it doesn't hide functionality behind a paywall'; 'You don't need to pay anything to use it but I chose to subscribe'); against that MON_GEM_GATE 47 (1.36%, 3.34★, 2017 → 2026: quests, hairstyles, backgrounds and pet food behind gems free players can barely earn — 'The quests and many customization items are stuck behind gem paywalls'), MON_P2W_PERCEIVED 19 (0.55%, 1.84★: 'After subscribing you are allotted the ability to buy 24 gems for only $6 more dollars'); the gem complaint is growing — 4.2% of E5 vs at most 1.0% earlier; stated purchasers (U_PAID 55) average 3.25★ and 15 of 55 report a purchase that went wrong.", "free core; subscription + gem currency; gems gate content", "mixed", "PR_FREE 68; NOT_REQUIRED 44; GEM_GATE 47 / 3.34★ (4.2% of E5); P2W 19 / 1.84★; U_PAID 55 / 3.25★", "product-rule", "Meaningful", "generalisable", ["14328108297", "13622777386", "13735335061", "13121830633", "1338112035", "2443195146"], "", "a second currency that free players cannot earn converts goodwill into 'pay-to-win'")

c(11, "§0.7; §3.6; §8.6", "feature", "The requests are for tracker basics as much as game content: U_REQ_ANY 563 (16.34%, 4.10★), rising 10.7% of E1 → 26.0% of E5 while crashes fall; tracker basics lead — REQ_STATS 71 (2.06%: history and statistics), REQ_CALENDAR 33 (0.96%), REQ_FREQ 45 (1.31%: '3 times a week'; 'there being no option for truly weekly tasks', 1★), REQ_REORDER 30, REQ_LISTS 20; game-side almost as large — REQ_CONTENT 79 (2.29%: more content, actual battles, an endgame; 'A progressão fica meio estagnada'), REQ_TRADE 12; 'if it had a calender for the habits and I could see how many days in a month I completed the task' carries 14 votes, more than any other request.", "no history/stats, no calendar, no flexible frequency", "complaint", "U_REQ_ANY 563 / 16.34% / 4.10★, 10.7% → 26.0%; STATS 71; FREQ 45; CALENDAR 33; REORDER 30; LISTS 20; CONTENT 79; TRADE 12", "must-have", "High-priority", "generalisable", ["3169036055", "12477691291", "14438914703", "1250294239", "1734640664"], "", "an eleven-year-old gamified tracker still lacks a calendar and stats")

c(12, "§0.8; §3.2 (segments); §8.9", "audience", "Users with ADHD are the fastest-growing audience and the most exposed to its flaws: USE_ADHD 71 (2.06%, 4.41★) — 6.0% of E5 vs 1.3%, 0.8%, 1.0% in E1–E3; USE_MENTAL 51 (1.48%, depression and anxiety); the instant reward of XP and gold is the mechanism they name ('Primera app que me ayuda con mi TDA'; 'I have ADHD and find it hard to do tasks, but this app has been a game changer'); the same audience names the failure modes: pop-ups that derail the task, punishments that feel arbitrary or absent ('ADHD, autism, and executive dysfunction, not helpful', 2★), too much stimulus ('Demasiados impulsos texto y provoca que te distraigas de las tareas', 2★), and the loss of a guild that worked as a support group.", "instant XP/gold reward; party accountability", "mixed", "USE_ADHD 71 / 2.06% / 4.41★, 6.0% of E5; USE_MENTAL 51", "do", "Meaningful", "generalisable", ["13463206718", "14432509862", "13882582042", "14446058814", "12975896573", "13838933613"], "", "")

c(13, "§2.3 table (verbatim); §2.4", "monetization", "Free / paid classification (verbatim): " + table("## 2.3 Free / paid / trial", 0) + " — the task manager, RPG progression, parties, quests from drops and challenges are free with no ads; subscription optional ($4.99/month; '$5/mo'); gems are the paid currency for quests, backgrounds, hairstyles, pet food and class change, and subscribers can buy gems with gold ('in order to earn gems with coins you have to pay a subscription'); a group plan (shared task lists) is paid and not usable in the iOS app per one reviewer; donations mentioned 2015–2018; no trial described; not established: the IAP list and gem prices, exact crash-wave release dates, whether the Ukrainian translation shipped, what share describe the iOS app vs the web.", "free core; optional sub; gem currency; paid group plan", "mixed", "MON_SUB 47; MON_GEMS 8; NOT_REQUIRED 44; GROUP_PLAN 4; DONATE 2; trial 0", "undecided", "table", "app-specific", ["3153284824", "13791199455"], "", "")

save("w")
